<?php require __DIR__.'/../includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if($pdo&&$id&&(int)$id!==(int)$_SESSION['admin_id'])$pdo->prepare("UPDATE users SET role='editor' WHERE id=?")->execute([$id]);header('Location: users.php');exit;}$rows=$pdo?$pdo->query('SELECT id,email,display_name,role,last_login_at,created_at FROM users ORDER BY created_at')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Users</h1><p><a href="dashboard.php">Dashboard</a></p><div class="card"><table style="width:100%"><tr><th>Email</th><th>Name</th><th>Role</th><th>Last login</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['email'])?></td><td><?=e($r['display_name'])?></td><td><?=e($r['role'])?></td><td><?=e($r['last_login_at']??'Never')?></td><td><?php if((int)$r['id']!==(int)$_SESSION['admin_id']&&$r['role']==='admin'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Demote to editor</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></main></body></html>

